package com.industrial.defect.service;
import com.industrial.defect.dto.keyboard.KeyboardInspectionResponse; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.MediaType; import org.springframework.http.client.SimpleClientHttpRequestFactory; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component public class KeyboardAnalysisClient { private final RestClient client; public KeyboardAnalysisClient(@Value("${keyboard.service.url}") String url,@Value("${keyboard.service.connect-timeout-ms:5000}") int connect,@Value("${keyboard.service.read-timeout-ms:300000}") int read){var f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(connect);f.setReadTimeout(read);client=RestClient.builder().baseUrl(url).requestFactory(f).build();} public KeyboardInspectionResponse analyze(byte[] image){var response=client.post().uri("/analyze").contentType(MediaType.APPLICATION_OCTET_STREAM).body(image).retrieve().body(KeyboardInspectionResponse.class);if(response==null||response.get("status")==null)throw new IllegalStateException("Keyboard worker returned an incomplete response.");return response;} public byte[] asset(String id,String name){return client.get().uri("/api/keyboard-assets/{id}/{name}",id,name).retrieve().body(byte[].class);} }
